implementation.snippet:
MOTButton(
    onClick = { onSave() },
    modifier = Modifier.fillMaxWidth(),
    enabled = !state.isSaving,
) {
    Text("Guardar gasto")
}

implementation.variantsSnippet:
// Secundaria con énfasis moderado
MOTTonalButton(onClick = onNext) { Text("Siguiente") }

// Alternativa o salida del flujo
MOTOutlinedButton(onClick = onCancel) { Text("Cancelar") }

// Baja prioridad / acciones de diálogo
MOTTextButton(onClick = onDiscard) { Text("Descartar") }
